pub fn is_sorted(a: &[i32]) -> bool {
    // Iterate through each pair of adjacent elements.
    // If any preceding element is greater than the following one,
    // the array is not sorted in nondecreasing order.
    for i in 1..a.len() {
        if a[i - 1] > a[i] {
            return false;
        }
    }
    true
}

